import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class FastInput {
        private final InputStream is;
        private final byte[] buffer = new byte[1 << 15];
        private int pos = 0, len = 0;

        FastInput(InputStream in) { is = in; }

        private int nextByte() throws IOException {
            if (pos >= len) {
                pos = 0;
                len = is.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[pos++];
        }

        int nextInt() throws IOException {
            int c;
            while ((c = nextByte()) <= 32) if (c == -1) return -1;
            int x = 0;
            while (c > 32) {
                x = x * 10 + c - '0';
                c = nextByte();
            }
            return x;
        }
    }

    FastInput input;

    public static void main(String[] args) {
        new CF1187G().process();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] graph;
    int nodes, edges;
    int[] potential, level, parentEdge;
    int[] src, dst, xorEdge, weight;
    int[] flow;

    void setup(int n, int m) {
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        potential = new int[n];
        level = new int[n];
        parentEdge = new int[n];
        src = new int[m];
        dst = new int[m];
        xorEdge = new int[m];
        weight = new int[m];
        flow = new int[m * 2];
        edges = 0;
    }

    void addConnection(int u, int v, int cap, int cost) {
        int idx = edges++;
        src[idx] = u;
        dst[idx] = v;
        xorEdge[idx] = u ^ v;
        weight[idx] = cost;
        flow[idx * 2] = cap;
        graph[u].add(idx * 2);
        graph[v].add(idx * 2 + 1);
    }

    int[] deque;
    int dqHead, dqTail, dqSize;
    boolean[] inDeque;

    void pushToDeque(int node) {
        if (inDeque[node]) return;
        if (dqHead + dqSize == deque.length) {
            if (dqSize * 2 <= deque.length) {
                System.arraycopy(deque, dqHead, deque, 0, dqSize);
                dqHead = 0;
            } else {
                int[] newDeque = new int[deque.length * 2];
                System.arraycopy(deque, dqHead, newDeque, 0, dqSize);
                deque = newDeque;
                dqHead = 0;
            }
        }
        deque[dqHead + dqSize++] = node;
        inDeque[node] = true;
    }

    int popFromDeque() {
        int node = deque[dqHead++];
        dqSize--;
        inDeque[node] = false;
        return node;
    }

    boolean findShortestPath(int source, int sink) {
        Arrays.fill(potential, INF);
        potential[source] = 0;
        dqHead = dqSize = 0;
        pushToDeque(source);

        while (dqSize > 0) {
            int u = popFromDeque();
            int newLevel = level[u] + 1;

            for (int edge : graph[u]) {
                if (flow[edge] > 0) {
                    int idx = edge >> 1;
                    int cost = (edge & 1) == 0 ? weight[idx] : -weight[idx];
                    int newPotential = potential[u] + cost;
                    int v = u ^ xorEdge[idx];

                    if (potential[v] > newPotential || 
                        (potential[v] == newPotential && level[v] > newLevel)) {
                        potential[v] = newPotential;
                        level[v] = newLevel;
                        parentEdge[v] = edge;
                        pushToDeque(v);
                    }
                }
            }
        }
        return potential[sink] != INF;
    }

    void pushFlow(int s, int t) {
        int minFlow = INF;
        for (int cur = t; cur != s; cur ^= xorEdge[parentEdge[cur] >> 1]) {
            minFlow = Math.min(minFlow, flow[parentEdge[cur]]);
        }
        for (int cur = t; cur != s; cur ^= xorEdge[parentEdge[cur] >> 1]) {
            int e = parentEdge[cur];
            flow[e] -= minFlow;
            flow[e ^ 1] += minFlow;
        }
    }

    void pushUnitFlow(int s, int t) {
        for (int cur = t; cur != s; cur ^= xorEdge[parentEdge[cur] >> 1]) {
            int e = parentEdge[cur];
            flow[e]--;
            flow[e ^ 1]++;
        }
    }

    int computeMinCost(int source, int sink) {
        while (findShortestPath(source, sink)) {
            pushUnitFlow(source, sink);
        }
        int total = 0;
        for (int i = 0; i < edges; i++) {
            total += weight[i] * flow[i * 2 + 1];
        }
        return total;
    }

    void process() {
        try {
            input = new FastInput(System.in);
            int n = input.nextInt();
            int m = input.nextInt();
            int k = input.nextInt();
            int c = input.nextInt();
            int d = input.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) special[i] = input.nextInt() - 1;

            List<Integer>[] adj = new ArrayList[n];
            for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = input.nextInt() - 1;
                int v = input.nextInt() - 1;
                adj[u].add(v);
                adj[v].add(u);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);
            setup(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int neighbor : adj[i]) {
                        int v = neighbor * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            addConnection(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    addConnection(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                addConnection(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(computeMinCost(totalNodes - 1, 0 * T + T - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
